export function Timeline({
  heading = "{{heading}}",
  orientation = "{{orientation}}",
  accent = "{{accent}}",
  showDetail = {{showDetail}},
  spacing = {{spacing}},
}) {
  const horizontal = orientation === "horizontal";
  const events = [
    { date: "2024-01-15", label: "15 Jan 2024", title: "Design spec finalised", detail: "Layout, tokens and component states signed off by the team." },
    { date: "2024-02-03", label: "3 Feb 2024", title: "Beta released to testers", detail: "Rolled out to 40 opt-in accounts for early feedback." },
    { date: "2024-03-01", label: "1 Mar 2024", title: "General availability", detail: "Launched to all customers with a migration guide." },
  ];
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 16, lineHeight: 1.5, color: "#241430", background: "#FAF7F2", padding: 20, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 16px", fontSize: 16, fontWeight: 700 }}>{heading}</h3>
      <ol style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: horizontal ? "row" : "column", gap: spacing, overflowX: horizontal ? "auto" : "visible" }}>
        {events.map((e) => (
          <li key={e.date} style={{ position: "relative", paddingLeft: horizontal ? 0 : 22, paddingTop: horizontal ? 22 : 0, minWidth: horizontal ? 160 : "auto" }}>
            <span aria-hidden="true" style={{ position: "absolute", left: horizontal ? 0 : 4, top: 4, width: 9, height: 9, borderRadius: "50%", background: accent }} />
            <time dateTime={e.date} style={{ display: "block", fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".03em", color: "#24143099" }}>{e.label}</time>
            <p style={{ margin: "2px 0 0", fontSize: 14, fontWeight: 600 }}>{e.title}</p>
            {showDetail && <p style={{ margin: "4px 0 0", fontSize: 13, color: "#241430b3" }}>{e.detail}</p>}
          </li>
        ))}
      </ol>
    </div>
  );
}
